using System.Diagnostics;
using System.Runtime.InteropServices;
using Microsoft.Win32;
using ReviveOS.Core;
namespace ReviveOS.Browser;
public record ChromeLaunchMeasurement(DateTime Utc,bool SeparateLightProfile,double WindowObservedMs,int WindowProcessId,string Conditions);
public static class ChromeRuntime {
 public static string LightProfile=>Path.Combine(State.Root,"ChromeLite");
 [DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr window);
 public static string? FindChrome(){if(!OperatingSystem.IsWindows())return null;var candidates=new List<string>();foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32}){try{using var root=RegistryKey.OpenBaseKey(hive,view);using var key=root.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\App Paths\chrome.exe");if(key?.GetValue(null) is string p)candidates.Add(p.Trim('"'));}catch(UnauthorizedAccessException){}}
  foreach(var folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)})candidates.Add(Path.Combine(folder,"Google","Chrome","Application","chrome.exe"));
  return candidates.FirstOrDefault(p=>Path.GetFileName(p).Equals("chrome.exe",StringComparison.OrdinalIgnoreCase)&&File.Exists(p));
 }
 public static string[] Arguments(bool light,string? page=null){if(page!=null&&page is not ("chrome://newtab/" or "chrome://settings/performance" or "chrome://settings/onStartup" or "chrome://extensions/" or "chrome://policy/"))throw new ArgumentException("Página interna não permitida");var args=new List<string>();if(light)args.Add("--user-data-dir="+LightProfile);if(page!=null){args.Add("--new-window");args.Add(page);}return args.ToArray();}
 public static void Open(bool light=false,string? page=null){var exe=FindChrome()??throw new IOException("Chrome não encontrado");var si=new ProcessStartInfo(exe){UseShellExecute=false};foreach(var a in Arguments(light,page))si.ArgumentList.Add(a);using var p=Process.Start(si);}
 static bool AnyRunning(){using var current=Process.GetCurrentProcess();foreach(var process in Process.GetProcessesByName("chrome")){using(process){try{if(process.SessionId==current.SessionId)return true;}catch(System.ComponentModel.Win32Exception){return true;}catch(InvalidOperationException){}}}return false;}
 public static async Task<ChromeLaunchMeasurement> MeasureLaunch(bool light,CancellationToken ct=default){if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException();if(AnyRunning())throw new InvalidOperationException("Chrome já está executando. Feche-o normalmente, salvando seus trabalhos. Nada será encerrado automaticamente.");var started=DateTime.UtcNow;var timer=Stopwatch.StartNew();Open(light);using var current=Process.GetCurrentProcess();while(timer.Elapsed<TimeSpan.FromSeconds(45)){ct.ThrowIfCancellationRequested();foreach(var process in Process.GetProcessesByName("chrome")){using(process){try{if(process.SessionId!=current.SessionId||process.StartTime.ToUniversalTime()<started.AddSeconds(-1))continue;var handle=process.MainWindowHandle;if(handle==IntPtr.Zero||!IsWindowVisible(handle))continue;var result=new ChromeLaunchMeasurement(DateTime.UtcNow,light,timer.Elapsed.TotalMilliseconds,process.Id,"Tempo observado até primeira janela Chrome visível; não mede página pronta. Cache não é expurgado. Primeiro uso do perfil pode exibir boas-vindas. Compare o mesmo perfil/estado/carga; perfil leve é experimento separado, sem ganho presumido.");State.Save(Path.Combine(State.Root,"benchmarks","chrome-"+Guid.NewGuid()+".json"),result);return result;}catch(System.ComponentModel.Win32Exception){}catch(InvalidOperationException){}}}await Task.Delay(100,ct);}throw new TimeoutException("Janela não detectada em 45 s. Chrome não foi encerrado. Não foi registrada medição de sucesso.");}
}
